import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = process.env.OPENCODE_CONFIG_DIR;
const dataRoot = path.join(ROOT, 'resources/skeleton');
const list = JSON.parse(fs.readFileSync(path.join(dataRoot, 'list_ThreejsGltf.json'), 'utf8'));
const entry = list.data.find(item => item.name === 'sheep');
if (!entry) throw new Error('sheep entry missing');
const dataPath = path.join(dataRoot, 'data', entry.skeleton);
const data = JSON.parse(fs.readFileSync(dataPath, 'utf8'));

const THREE = await import(pathToFileURL(path.join(ROOT, 'tools/dist-depend/three-bundle.mjs')).href);

const bones = data.bones.map(item => {
  const [name, value] = Object.entries(item)[0];
  return {
    name: name.trim(),
    parentName: (value.parent || '').trim() || undefined,
    pos: Array.isArray(value.pos) ? value.pos : [0, 0, 0],
    rot: Array.isArray(value.rot) ? value.rot : [0, 0, 0, 1],
    scale: Array.isArray(value.scale) ? value.scale : [1, 1, 1],
  };
});

const round = (v, d) => {
  const r = Number(Number(v).toFixed(d));
  return Object.is(r, -0) ? 0 : r;
};

const worldMatrices = new Map();
for (const bone of bones) {
  const m = new THREE.Matrix4().compose(
    new THREE.Vector3(...bone.pos),
    new THREE.Quaternion(...bone.rot),
    new THREE.Vector3(...bone.scale),
  );
  worldMatrices.set(bone.name, m);
}

const defs = bones.map(bone => {
  const world = worldMatrices.get(bone.name);
  const parent = bone.parentName ? worldMatrices.get(bone.parentName) : null;
  const local = parent ? parent.clone().invert().multiply(world) : world.clone();
  const pos = new THREE.Vector3();
  const quat = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  local.decompose(pos, quat, scale);
  return {
    name: bone.name,
    parentName: bone.parentName,
    pos: [round(pos.x, 4), round(pos.y, 4), round(pos.z, 4)],
    rot: [round(quat.x, 6), round(quat.y, 6), round(quat.z, 6), round(quat.w, 6)],
    scale: [round(scale.x, 6), round(scale.y, 6), round(scale.z, 6)],
  };
});

const byName = new Map(defs.map(def => [def.name, def]));
const worldOf = name => {
  const chain = [];
  let current = byName.get(name);
  while (current) {
    chain.unshift(current);
    current = current.parentName ? byName.get(current.parentName) : null;
  }
  const m = new THREE.Matrix4();
  for (const node of chain) {
    m.multiply(new THREE.Matrix4().compose(
      new THREE.Vector3(...node.pos),
      new THREE.Quaternion(...node.rot),
      new THREE.Vector3(...node.scale),
    ));
  }
  return m;
};

for (const def of defs) {
  const m = worldOf(def.name);
  const p = new THREE.Vector3().setFromMatrixPosition(m);
  def.worldPos = [round(p.x, 4), round(p.y, 4), round(p.z, 4)];
}

const counts = new Map();
for (const def of defs) counts.set(def.name, (counts.get(def.name) || 0) + 1);
const names = new Set(defs.map(d => d.name));
const validation = {
  roots: defs.filter(d => !d.parentName).map(d => d.name),
  duplicateNames: [...counts].filter(([, c]) => c > 1).map(([name, count]) => ({ name, count })),
  selfParents: defs.filter(d => d.parentName === d.name).map(d => d.name),
  missingParents: defs.filter(d => d.parentName && !names.has(d.parentName)).map(d => ({ name: d.name, parentName: d.parentName })),
  keyBonePresence: Object.fromEntries(Object.entries(entry.keyBones || {}).map(([role, value]) => [
    role,
    { name: value.name, present: names.has(value.name), consistent: value.consistent === true },
  ])),
};
validation.ok = validation.duplicateNames.length === 0 && validation.selfParents.length === 0
  && validation.missingParents.length === 0
  && Object.values(validation.keyBonePresence).every(item => item.present);

const metaSkeleton = {
  entryName: entry.name,
  sourceListFile: 'resources/skeleton/list_ThreejsGltf.json',
  sourceDataFile: `resources/skeleton/data/${entry.skeleton}`,
  scriptFile: entry.script ? `resources/skeleton/data/${entry.script}` : undefined,
  controllerResourcePath: data.controller || undefined,
  controllerResourceType: data.controller ? 'RuntimeAnimatorController' : undefined,
  avatarResourcePath: data.avatar || undefined,
  avatarResourceType: data.avatar ? 'Avatar' : undefined,
  noMeshBones: Array.isArray(data.NoMeshBones) ? data.NoMeshBones : [],
  boneCount: bones.length,
  hierarchyPreserved: validation.ok,
  dataFormat: 'threejs-global-quaternion',
};

const result = {
  entry,
  source: {
    listFile: 'resources/skeleton/list_ThreejsGltf.json',
    dataFile: `resources/skeleton/data/${entry.skeleton}`,
    scriptFile: entry.script ? `resources/skeleton/data/${entry.script}` : undefined,
  },
  skeletonFacts: {
    controller: data.controller,
    avatar: data.avatar,
    bounds: data.bounds,
    noMeshBones: data.NoMeshBones,
    boneCount: bones.length,
  },
  validation,
  metaSkeleton,
  controlDefs: defs,
};

process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
if (!validation.ok) process.exitCode = 2;

