import fs from 'node:fs';
import { pathToFileURL } from 'node:url';
const ROOT = process.env.OPENCODE_CONFIG_DIR;
const THREE = await import(pathToFileURL(ROOT + '/tools/dist-depend/three-bundle.mjs').href);
const data = JSON.parse(fs.readFileSync('/var/folders/9t/1jhwn7p90xj8jy29h2fvgc2c0000gn/T/opencode/sheep/controls.json','utf8'));
const byName = new Map(data.controlDefs.map(d=>[d.name,d]));
function worldMatrix(name){const chain=[];let c=byName.get(name);while(c){chain.unshift(c);c=c.parentName?byName.get(c.parentName):null;}
 const m=new THREE.Matrix4();for(const n of chain){m.multiply(new THREE.Matrix4().compose(new THREE.Vector3(...n.pos),new THREE.Quaternion(...n.rot),new THREE.Vector3(...n.scale)));}return m;}
const headM = worldMatrix('SHEEP_ Head');
const headQ = new THREE.Quaternion().setFromRotationMatrix(headM);
for (const side of ['L','R']) {
  const sign = side==='L'?1:-1;
  const pivot = new THREE.Object3D();
  pivot.position.set(sign*0.062,-0.535,0.717);
  pivot.rotation.set(sign*0.05, sign*0.62, 0);
  pivot.updateMatrixWorld(true);
  const pivotQ = pivot.quaternion.clone();
  const localQ = headQ.clone().invert().multiply(pivotQ);
  const axes = {};
  for (const [k,v] of Object.entries({X:[1,0,0],Y:[0,1,0],Z:[0,0,1]})) {
    const dir = new THREE.Vector3(...v).applyQuaternion(pivotQ);
    axes[k]=[+dir.x.toFixed(3),+dir.y.toFixed(3),+dir.z.toFixed(3)];
  }
  console.log(side, 'localQuat', localQ.toArray().map(v=>+v.toFixed(4)), 'worldAxes', JSON.stringify(axes));
}
// tail pivot
const tailM = worldMatrix('SHEEP_ Tail2');
const tailQ = new THREE.Quaternion().setFromRotationMatrix(tailM);
console.log('tail2 world quat', tailQ.toArray().map(v=>+v.toFixed(4)));
EOF
