display.text:
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { createCreatureControlNodeDefs, selectCreatureSkeletonEntry } from './creature_ref.js';
import { localTreeToGlobal } from './transform-converter.js';

const AGENT_RUNTIME_ROOT = resolveAgentRuntimeRoot();
const DEFAULT_SKELETON_ROOT = path.join(AGENT_RUNTIME_ROOT, 'resources/skeleton');
const POSITION_DECIMALS = 4;
const QUATERNION_DECIMALS = 6;
const SCALE_DECIMALS = 6;
const INLINE_ARRAY_KEYS = new Set(['pos', 'rot', 'scale', 'worldPos']);
const INDENT_SIZE = 2;

function resolveAgentRuntimeRoot() {
  const envRoot = process.env.OPENCODE_CONFIG_DIR;
  if (!envRoot || !envRoot.trim()) {
    throw new Error('OPENCODE_CONFIG_DIR is required to resolve agent-runtime resources.');
  }
  return path.resolve(envRoot);
}

function roundNumber(value, decimals) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return value;
  }
  const rounded = Number(value.toFixed(decimals));
  return Object.is(rounded, -0) ? 0 : rounded;
}

function roundPositionNumber(value) {
  return roundNumber(value, POSITION_DECIMALS);
}

function roundQuaternionNumber(value) {
  return roundNumber(value, QUATERNION_DECIMALS);
}

function roundScaleNumber(value) {
  return roundNumber(value, SCALE_DECIMALS);
}

function roundPositionVector(value) {
  return Array.isArray(value) ? value.map(roundPositionNumber) : value;
}

function roundQuaternionVector(value) {
  return Array.isArray(value) ? value.map(roundQuaternionNumber) : value;
}

function roundScaleVector(value) {
  return Array.isArray(value) ? value.map(roundScaleNumber) : value;
}

function roundControlDefVectors(def) {
  return {
    ...def,
    pos: roundPositionVector(def.pos),
    rot: roundQuaternionVector(def.rot),
    scale: roundScaleVector(def.scale),
  };
}

function shouldInlineArray(key, value) {
  return INLINE_ARRAY_KEYS.has(key)
    && Array.isArray(value)
    && value.length <= 4
    && value.every(item => typeof item === 'number' && Number.isFinite(item));
}

function formatJsonValue(value, level = 0, key = '') {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    if (shouldInlineArray(key, value)) {
      return `[${value.map(item => JSON.stringify(item)).join(', ')}]`;
    }
    if (value.length === 0) {
      return '[]';
    }
    const indent = ' '.repeat(level * INDENT_SIZE);
    const childIndent = ' '.repeat((level + 1) * INDENT_SIZE);
    return `[\n${value.map(item => `${childIndent}${formatJsonValue(item, level + 1)}`).join(',\n')}\n${indent}]`;
  }

  const entries = Object.entries(value).filter(([, entryValue]) => entryValue !== undefined);
  if (entries.length === 0) {
    return '{}';
  }

  const indent = ' '.repeat(level * INDENT_SIZE);
  const childIndent = ' '.repeat((level + 1) * INDENT_SIZE);
  const lines = entries.map(([entryKey, entryValue]) => (
    `${childIndent}${JSON.stringify(entryKey)}: ${formatJsonValue(entryValue, level + 1, entryKey)}`
  ));
  return `{\n${lines.join(',\n')}\n${indent}}`;
}

function formatOutputJson(value, pretty) {
  return pretty ? formatJsonValue(value) : JSON.stringify(value);
}

function parseArgs(argv) {
  const args = {
    creature: '',
    skeletonRoot: DEFAULT_SKELETON_ROOT,
    pretty: true,
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--creature') {
      args.creature = argv[index + 1] || '';
      index += 1;
    } else if (arg === '--skeleton-root') {
      args.skeletonRoot = path.resolve(argv[index + 1] || '');
      index += 1;
    } else if (arg === '--compact') {
      args.pretty = false;
    }
  }

  if (!args.creature) {
    throw new Error('Usage: prepare-control-defs.mjs --creature <entry-name>');
  }

  return args;
}

function extractRawEntry(manifest, entryName) {
  const normalizedName = String(entryName || '').trim().toLowerCase();
  const data = Array.isArray(manifest?.data) ? manifest.data : [];
  return data.find(item => String(item?.name || '').trim().toLowerCase() === normalizedName) || null;
}

function validateDefs(defs, rawEntry) {
  const counts = new Map();
  for (const def of defs) {
    counts.set(def.name, (counts.get(def.name) || 0) + 1);
  }

  const names = new Set(defs.map(def => def.name));
  const duplicateNames = [...counts.entries()]
    .filter(([, count]) => count > 1)
    .map(([name, count]) => ({ name, count }));
  const selfParents = defs
    .filter(def => def.parentName && def.parentName === def.name)
    .map(def => def.name);
  const missingParents = defs
    .filter(def => def.parentName && !names.has(def.parentName))
    .map(def => ({ name: def.name, parentName: def.parentName }));

  const keyBones = rawEntry?.keyBones && typeof rawEntry.keyBones === 'object' ? rawEntry.keyBones : {};
  const keyBonePresence = Object.fromEntries(
    Object.entries(keyBones).map(([role, value]) => {
      const nodeName = typeof value?.name === 'string' ? value.name : '';
      return [
        role,
        {
          name: nodeName,
          present: !!nodeName && names.has(nodeName),
          consistent: value?.consistent === true,
        },
      ];
    }),
  );

  return {
    ok: duplicateNames.length === 0 && selfParents.length === 0 && missingParents.length === 0
      && Object.values(keyBonePresence).every(item => item.present),
    roots: defs.filter(def => !def.parentName).map(def => def.name),
    duplicateNames,
    selfParents,
    missingParents,
    keyBonePresence,
  };
}

function buildMetaSkeleton(entry, skeletonData, validation) {
  return {
    entryName: entry.name,
    sourceListFile: 'resources/skeleton/list_ThreejsGltf.json',
    sourceDataFile: `resources/skeleton/data/${entry.skeleton}`,
    scriptFile: entry.script ? `resources/skeleton/data/${entry.script}` : undefined,
    controllerResourcePath: skeletonData.controller || undefined,
    controllerResourceType: skeletonData.controller ? 'RuntimeAnimatorController' : undefined,
    avatarResourcePath: skeletonData.avatar || undefined,
    avatarResourceType: skeletonData.avatar ? 'Avatar' : undefined,
    noMeshBones: Array.isArray(skeletonData.NoMeshBones) ? skeletonData.NoMeshBones : [],
    boneCount: Array.isArray(skeletonData.bones) ? skeletonData.bones.length : undefined,
    hierarchyPreserved: validation.ok,
    dataFormat: 'threejs-global-quaternion',
  };
}

function attachWorldPositions(controlDefs) {
  const roundedControlDefs = controlDefs.map(roundControlDefVectors);
  const worldTree = localTreeToGlobal({
    isGlobal: false,
    platform: 'ThreeJS',
    rotationMode: 'quaternion',
    nodes: roundedControlDefs,
  });
  return roundedControlDefs.map((def, index) => {
    const worldDef = worldTree.nodes[index];
    return {
      ...def,
      worldPos: roundPositionVector(Array.isArray(worldDef?.pos) ? worldDef.pos : [...def.pos]),
    };
  });
}

export function prepareCreatureControlDefs(options) {
  const creature = String(options?.creature || '').trim();
  if (!creature) {
    throw new Error('creature entry name is required.');
  }
  const skeletonRoot = path.resolve(options?.skeletonRoot || DEFAULT_SKELETON_ROOT);
  const listPath = path.join(skeletonRoot, 'list_ThreejsGltf.json');
  const manifestListText = fs.readFileSync(listPath, 'utf8');
  const manifest = JSON.parse(manifestListText);
  const entry = selectCreatureSkeletonEntry(manifestListText, creature);
  const rawEntry = extractRawEntry(manifest, entry.name);
  const dataPath = path.join(skeletonRoot, 'data', entry.skeleton);
  const manifestDataText = fs.readFileSync(dataPath, 'utf8');
  const skeletonData = JSON.parse(manifestDataText);
  const localControlDefs = createCreatureControlNodeDefs({
    manifestListText,
    manifestDataText,
    creatureName: entry.name,
  });
  const controlDefs = attachWorldPositions(localControlDefs);
  const validation = validateDefs(controlDefs, rawEntry);
  return {
    entry,
    source: {
      listFile: path.relative(AGENT_RUNTIME_ROOT, listPath),
      dataFile: path.relative(AGENT_RUNTIME_ROOT, dataPath),
      scriptFile: entry.script ? `resources/skeleton/data/${entry.script}` : undefined,
    },
    skeletonFacts: {
      controller: skeletonData.controller || undefined,
      avatar: skeletonData.avatar || undefined,
      bounds: skeletonData.bounds || undefined,
      noMeshBones: Array.isArray(skeletonData.NoMeshBones) ? skeletonData.NoMeshBones : [],
      boneCount: Array.isArray(skeletonData.bones) ? skeletonData.bones.length : undefined,
    },
    validation,
    metaSkeleton: buildMetaSkeleton(entry, skeletonData, validation),
    controlDefs,
  };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const result = prepareCreatureControlDefs({
    creature: args.creature,
    skeletonRoot: args.skeletonRoot,
  });

  const output = formatOutputJson(result, args.pretty);
  process.stdout.write(`${output}\n`);

  if (!result.validation.ok) {
    process.exitCode = 2;
  }
}

const isDirectExecution = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectExecution) {
  try {
    main();
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

