import { tool } from '@opencode-ai/plugin';
import { WORLDPLAY_MODULE_RESOURCE_ID_PATTERN } from '@ai-world-creator/worldplay-toolkit-core';
import { WorldplayArchiveFileUtils } from './archive/common/worldplay-archive-file-utils';
import { WorldplayToolContext } from './archive/common/worldplay-tool-context';
import { WorldplayModuleArchivePaths } from './archive/module/model-archive-utils/worldplay-module-archive-paths';
import { WorldplayModuleArchiveTarget } from './archive/module/model-archive-utils/worldplay-module-archive-target';
import { WorldplayModuleAuthorMetaStore } from './archive/module/model-archive-utils/worldplay-module-author-meta-store';
import { RigRuntimeFactsBuilder } from './archive/module/model-static-bundle/rig-runtime-facts';
import { WorldplayStaticPreviewAnalyzer } from './archive/module/model-static-bundle/worldplay-static-preview-analyzer';
import { WorldplayStaticSkeletonSource } from './archive/module/model-static-bundle/worldplay-static-skeleton-source';

function stringifyResult(value: Record<string, unknown>): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}

export default tool({
  description: [
    'Generate runtime rig facts from a geometry Module preview and static/skeleton.json.',
    'Writes assets/module/<resourceId>/static/rig-runtime-facts.json for motion, animation, and mounted Lua behavior.',
    'Run this only after the geometry model and skeleton are complete; do not hand-edit the generated file.',
  ].join(' '),
  args: {
    resourceId: tool.schema
      .string()
      .regex(WORLDPLAY_MODULE_RESOURCE_ID_PATTERN)
      .optional()
      .describe(
        'Module resource id. It must use lowercase module- format. Use this or resourceRoot; if both are provided, they must agree.',
      ),
    resourceRoot: tool.schema
      .string()
      .optional()
      .describe('Safe Module resource root, exactly assets/module/<resourceId>. It must agree with resourceId when both are provided.'),
  },
  async execute(args, context) {
    const workspaceRoot = WorldplayToolContext.resolveWorldplayWorkspaceRoot(context);
    const archiveTarget = WorldplayModuleArchiveTarget.resolve(workspaceRoot, args);
    const archiveContext = WorldplayModuleArchivePaths.resolveArchiveWorkspaceContext({
      adapter: WorldplayToolContext.getThreeAdapter(),
      resourceId: archiveTarget.resourceId,
      resourceRoot: archiveTarget.resourceRoot,
      workspaceRoot,
    });
    const skeleton = WorldplayStaticSkeletonSource.readStaticSkeleton(archiveContext);
    if (!skeleton) {
      throw new Error(`${archiveContext.resourceRoot}/static/skeleton.json is required.`);
    }

    const baseAuthorMeta = WorldplayModuleAuthorMetaStore.readAuthorMeta({
      context: archiveContext,
      required: true,
    });
    const authorMeta = WorldplayStaticSkeletonSource.mergeSkeletonIntoAuthorMeta(archiveContext, baseAuthorMeta);
    const glbStructure = await WorldplayStaticPreviewAnalyzer.analyze(archiveContext, context.abort);
    const runtimeFacts = RigRuntimeFactsBuilder.buildRigRuntimeFacts(authorMeta, glbStructure);
    if (!runtimeFacts) {
      throw new Error(
        `${WorldplayModuleAuthorMetaStore.resolveMetaSourceLabel(archiveContext)} category must be "humanoid" or "creature" when generating rig runtime facts.`,
      );
    }

    WorldplayArchiveFileUtils.writeJsonAtomically(archiveContext.staticRuntimeFactsPath, runtimeFacts);

    return stringifyResult({
      schemaVersion: 1,
      status: 'completed',
      resourceId: archiveContext.resourceId,
      resourceRoot: archiveContext.resourceRoot,
      outputPath: `${archiveContext.resourceRoot}/static/rig-runtime-facts.json`,
      rigFamily: runtimeFacts.rigFamily,
      capabilityHint: runtimeFacts.capabilityHint,
    });
  },
});
